import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def validate_invoice_fields(invoice_path: str, required_fields: list[str], min_confidence: float) -> dict:
    """
    Validates required structured fields and their confidence scores in an invoice using Azure Document Intelligence.

    Args:
        invoice_path: The path to the invoice file.
        required_fields: A list of field names that must be present and meet the confidence threshold.
        min_confidence: The minimum confidence score required for each field.

    Returns:
        A dictionary containing the validation results.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("Please set the AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(invoice_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-invoice", f
        )
        invoice_result: AnalyzeResult = poller.result()

    validation_results = {
        "is_valid": True,
        "missing_fields": [],
        "low_confidence_fields": {},
        "extracted_data": {},
    }

    if invoice_result.documents:
        invoice = invoice_result.documents[0]
        extracted_fields = invoice.fields if invoice.fields else {}

        for field_name in required_fields:
            field = extracted_fields.get(field_name)
            if not field:
                validation_results["is_valid"] = False
                validation_results["missing_fields"].append(field_name)
            elif field.confidence is None or field.confidence < min_confidence:
                validation_results["is_valid"] = False
                validation_results["low_confidence_fields"][field_name] = field.confidence

            # Store extracted data for all fields, regardless of confidence/requirement status
            if field and field.content:
                validation_results["extracted_data"][field_name] = {
                    "value": field.content,
                    "confidence": field.confidence
                }
            elif field: # Field exists but has no content
                validation_results["extracted_data"][field_name] = {
                    "value": None,
                    "confidence": field.confidence
                }
            else: # Field was not found at all
                validation_results["extracted_data"][field_name] = {
                    "value": None,
                    "confidence": None
                }

    else:
        validation_results["is_valid"] = False
        validation_results["error"] = "No invoice documents found in the analysis result."
        for field_name in required_fields:
            validation_results["missing_fields"].append(field_name)

    return validation_results
